#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────


# The factory's setup wizard. `setup` runs it from the home repo and hands it,
# by environment, what the factory's TypeScript defines once:
#   ENV_FILE            the home repo's .sandcastle/.env
#   WIZARD_PHASES       phases, space-separated
#   WIZARD_EFFORTS      one line per provider: its name, then its efforts, lowest first
#   WIZARD_SANDBOXES    sandbox choices
#   WIZARD_HOME_SLUG    owner/name of the home repo
#   WIZARD_REPOS        one line per app repo: its .env key, then its name
#   WIZARD_BASE_IMAGE   the image every repo image starts FROM
#   WIZARD_IMAGES       one line per repo: its image, then its Containerfile
#   WIZARD_FACTORY_DIR  build context of the base image

: "${WIZARD_PHASES:?run it with: npm run sandcastle -- setup}"
read -r -a PHASES <<< "$WIZARD_PHASES"
read -r -a SANDBOXES <<< "$WIZARD_SANDBOXES"
read -r -a PROVIDERS <<< "$(awk '{ printf "%s ", $1 }' <<< "$WIZARD_EFFORTS")"
CLAUDE_ALIASES=(opus sonnet haiku fable)
PROV=(); MODEL=(); EFF=()   # per phase, in PHASES order
COPILOT_MODELS=(); COPILOT_READ=0
DONE=0                      # "done, keep the rest": skip every filled stage

# ── Arrow-key menus: our addition, not wizard library ─────────────────────

# read_key sets KEY to up, down, left, right, enter, esc, or the character typed.
read_key() {
  local k rest=""
  IFS= read -rsn1 k || exit 1
  if [[ "$k" == $'\e' ]]; then
    IFS= read -rsn2 -t 0.1 rest || true
    case "$rest" in
      '[A'|OA) KEY=up ;;
      '[B'|OB) KEY=down ;;
      '[C'|OC) KEY=right ;;
      '[D'|OD) KEY=left ;;
      *) KEY=esc ;;
    esac
  elif [[ -z "$k" || "$k" == $'\r' ]]; then KEY=enter
  else KEY="$k"; fi
}

# redraw "Name" repaints the current stage's screen from the top.
redraw() {
  printf '\033[H\033[J'
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# menu VAR CURRENT "Stage" "Intro" ITEM... lets the human pick an ITEM with
# ↑↓ and Enter, cursor first on index CURRENT; sets VAR to the picked index,
# or -1 on Esc. Long lists scroll.
menu() {
  local var="$1" cur="$2" name="$3" intro="$4" n i top height
  shift 4
  n=$#
  local items=("$@")
  height=$(( $(tput lines 2>/dev/null || echo 24) - 8 ))
  if (( height < 5 )); then height=5; fi
  while :; do
    redraw "$name"
    if [[ -n "$intro" ]]; then say "$intro"; fi
    note "↑↓ move · Enter pick · Esc back"
    printf '\n'
    top=$(( cur - height / 2 ))
    if (( top > n - height )); then top=$(( n - height )); fi
    if (( top < 0 )); then top=0; fi
    for (( i = top; i < n && i < top + height; i++ )); do
      if (( i == cur )); then printf '  %s❯ %s%s\n' "$BOLD" "${items[i]}" "$RESET"
      else printf '    %s\n' "${items[i]}"; fi
    done
    if (( n > height )); then note "($((cur + 1))/$n)"; fi
    read_key
    case "$KEY" in
      up) cur=$(( (cur + n - 1) % n )) ;;
      down) cur=$(( (cur + 1) % n )) ;;
      enter) printf -v "$var" '%s' "$cur"; return 0 ;;
      esc) printf -v "$var" '%s' -1; return 0 ;;
    esac
  done
}

# ── Helpers ───────────────────────────────────────────────────────────────

# skip counts a stage that has nothing to ask, so progress stays true.
skip() { _STAGE_INDEX=$((_STAGE_INDEX + 1)); }

current() { _existing "$1" || true; }
filled() { [[ -n "$(current "$1")" ]]; }

# save KEY VALUE writes KEY unless ENV_FILE already holds VALUE.
save() { [[ "$(current "$1")" == "$2" ]] || write_env "$1" "$2"; }

# index_of VALUE ITEM... prints VALUE's index among the ITEMs, or -1.
index_of() {
  local value="$1" i=0 item
  shift
  for item in "$@"; do
    if [[ "$item" == "$value" ]]; then printf '%s' "$i"; return 0; fi
    i=$((i + 1))
  done
  printf '%s' -1
}

# efforts_of PROVIDER prints the efforts PROVIDER accepts, lowest first.
efforts_of() { awk -v p="$1" '$1 == p { $1 = ""; print substr($0, 2) }' <<< "$WIZARD_EFFORTS"; }

# snap_effort FROM EFFORT TO prints EFFORT if provider TO accepts it, else the
# nearest one TO accepts, looking down FROM's efforts first, then up.
snap_effort() {
  local effort="$2" i j old=() new=()
  read -r -a old <<< "$(efforts_of "$1")"
  read -r -a new <<< "$(efforts_of "$3")"
  if (( $(index_of "$effort" "${new[@]}") >= 0 )); then printf '%s' "$effort"; return 0; fi
  i=$(index_of "$effort" "${old[@]+"${old[@]}"}")
  if (( i >= 0 )); then
    for (( j = i; j >= 0; j-- )); do
      if (( $(index_of "${old[j]}" "${new[@]}") >= 0 )); then printf '%s' "${old[j]}"; return 0; fi
    done
    for (( j = i; j < ${#old[@]}; j++ )); do
      if (( $(index_of "${old[j]}" "${new[@]}") >= 0 )); then printf '%s' "${old[j]}"; return 0; fi
    done
  fi
  printf '%s' "${new[${#new[@]} / 2]}"
}

uses_provider() { (( $(index_of "$1" "${PROV[@]}") >= 0 )); }

# load_copilot_models reads the model list of Copilot CLI's own config help, once; no token needed.
load_copilot_models() {
  local out m
  if (( COPILOT_READ )); then return 0; fi
  COPILOT_READ=1
  note "reading Copilot models…"
  out=$(npx -y @github/copilot help config 2>/dev/null | awk '
    /^[[:space:]]*`model`:/ { on = 1; next }
    on && /^[[:space:]]+- "/ { sub(/^[[:space:]]+- "/, ""); sub(/"[[:space:]]*$/, ""); print; next }
    { on = 0 }') || out=""
  while IFS= read -r m; do
    if [[ -n "$m" ]]; then COPILOT_MODELS+=("$m"); fi
  done <<< "$out"
}

# pick_model "Title" PROVIDER MODEL opens the model list, cursor on MODEL; sets
# PICK_PROVIDER and PICK_MODEL. Fails on Esc.
pick_model() {
  local title="$1" providers=() models=() items=() m cur choice
  load_copilot_models
  for m in "${CLAUDE_ALIASES[@]}"; do providers+=(claudeCode); models+=("$m"); done
  for m in "${COPILOT_MODELS[@]+"${COPILOT_MODELS[@]}"}"; do providers+=(copilot); models+=("$m"); done
  cur=${#models[@]}
  for (( m = 0; m < ${#models[@]}; m++ )); do
    items+=("$(printf '%-11s %s' "${providers[m]}" "${models[m]}")")
    if [[ "${providers[m]}" == "$2" && "${models[m]}" == "$3" ]]; then cur=$m; fi
  done
  if [[ -z "$3" ]]; then cur=0; fi
  menu choice "$cur" "Models" "$title" "${items[@]}" "enter your own…"
  if (( choice < 0 )); then return 1; fi
  if (( choice < ${#models[@]} )); then
    PICK_PROVIDER=${providers[choice]}; PICK_MODEL=${models[choice]}
    return 0
  fi
  printf '\n'
  ask OWN_MODEL "Model name (full or alias):" || return 1
  if [[ -z "$OWN_MODEL" ]]; then return 1; fi
  cur=$(index_of "$2" "${PROVIDERS[@]}")
  menu choice "$(( cur < 0 ? 0 : cur ))" "Models" "Provider of $OWN_MODEL" "${PROVIDERS[@]}"
  if (( choice < 0 )); then return 1; fi
  PICK_PROVIDER=${PROVIDERS[choice]}; PICK_MODEL=$OWN_MODEL
}

# set_model I PROVIDER MODEL gives phase I a model, snapping its effort to the provider.
set_model() {
  EFF[$1]=$(snap_effort "${PROV[$1]}" "${EFF[$1]}" "$2")
  PROV[$1]=$2; MODEL[$1]=$3
}

# cycle_effort I STEP moves phase I's effort by STEP within its provider's efforts, wrapping.
cycle_effort() {
  local list=() i
  read -r -a list <<< "$(efforts_of "${PROV[$1]}")"
  if (( ${#list[@]} == 0 )); then return 0; fi
  i=$(index_of "${EFF[$1]}" "${list[@]}")
  if (( i < 0 )); then i=$(( $2 > 0 ? -1 : 0 )); fi
  EFF[$1]=${list[(i + $2 + ${#list[@]}) % ${#list[@]}]}
}

# ── Stages ────────────────────────────────────────────────────────────────

models_stage() {
  local n=${#PHASES[@]} i cur=0 problem="" phase effort choice list=()
  for (( i = 0; i < n; i++ )); do
    PROV[i]=$(current "${PHASES[i]}_PROVIDER")
    MODEL[i]=$(current "${PHASES[i]}_MODEL")
    EFF[i]=$(current "${PHASES[i]}_EFFORT")
  done
  stage "Models"
  while :; do
    redraw "Models"
    note "↑↓ move · ←→ effort · Enter on a phase: model list"
    printf '\n'
    for (( i = 0; i < n + 3; i++ )); do
      if (( i == n )); then printf '\n'; fi
      if (( i == cur )); then printf '  %s❯ ' "$BOLD"; else printf '    '; fi
      case $(( i < n ? -1 : i - n )) in
        -1) printf '%-10s %-11s %-22s ‹ %s ›' "${PHASES[i]}" "${PROV[i]:--}" "${MODEL[i]:--}" "${EFF[i]:--}" ;;
        0) printf 'all phases at once…' ;;
        1) printf 'next →' ;;
        2) printf 'done, keep the rest' ;;
      esac
      printf '%s\n' "$RESET"
    done
    if [[ -n "$problem" ]]; then printf '\n'; warn "$problem"; problem=""; fi
    read_key
    case "$KEY" in
      up) cur=$(( (cur + n + 2) % (n + 3) )) ;;
      down) cur=$(( (cur + 1) % (n + 3) )) ;;
      left) if (( cur < n )); then cycle_effort "$cur" -1; fi ;;
      right) if (( cur < n )); then cycle_effort "$cur" 1; fi ;;
      enter)
        if (( cur < n )); then
          if pick_model "${PHASES[cur]} model" "${PROV[cur]}" "${MODEL[cur]}"; then set_model "$cur" "$PICK_PROVIDER" "$PICK_MODEL"; fi
        elif (( cur == n )); then
          if pick_model "Model of every phase" "${PROV[0]}" "${MODEL[0]}"; then
            effort=$(snap_effort "${PROV[0]}" "${EFF[0]}" "$PICK_PROVIDER")
            read -r -a list <<< "$(efforts_of "$PICK_PROVIDER")"
            menu choice "$(index_of "$effort" "${list[@]}")" "Models" "Effort of every phase" "${list[@]}"
            if (( choice >= 0 )); then
              for (( i = 0; i < n; i++ )); do PROV[i]=$PICK_PROVIDER; MODEL[i]=$PICK_MODEL; EFF[i]=${list[choice]}; done
            fi
          fi
        else
          for (( i = n - 1; i >= 0; i-- )); do
            if [[ -z "${PROV[i]}" || -z "${MODEL[i]}" || -z "${EFF[i]}" ]]; then problem="${PHASES[i]} has no model yet: Enter on it."; cur=$i; fi
          done
          if [[ -z "$problem" ]]; then
            if (( cur == n + 2 )); then DONE=1; fi
            break
          fi
        fi ;;
    esac
  done
  printf '\n'
  for (( i = 0; i < n; i++ )); do
    phase=${PHASES[i]}
    save "${phase}_PROVIDER" "${PROV[i]}"
    save "${phase}_MODEL" "${MODEL[i]}"
    save "${phase}_EFFORT" "${EFF[i]}"
  done
}

# sandbox_ready SANDBOX: the tool SANDBOX needs is installed, or its install link is shown.
sandbox_ready() {
  case "$1" in
    podman) command -v podman >/dev/null 2>&1 || { warn "podman is missing: https://podman.io/docs/installation"; return 1; } ;;
    docker) command -v docker >/dev/null 2>&1 || { warn "docker is missing: https://docs.docker.com/get-started/get-docker/"; return 1; } ;;
  esac
}

prerequisites_stage() {
  local node_major item ok=() missing=()
  node_major=$(node -p 'process.versions.node.split(".")[0]' 2>/dev/null || echo 0)
  if (( node_major >= 22 )); then ok+=("Node $node_major"); else missing+=("Node 22+: https://nodejs.org/en/download"); fi
  if ! command -v gh >/dev/null 2>&1; then missing+=("gh: https://cli.github.com")
  elif ! gh auth status >/dev/null 2>&1; then missing+=("gh login: run gh auth login")
  else ok+=("gh logged in"); fi
  if (( DONE )) && (( ${#missing[@]} == 0 )) && sandbox_ready "$(current SANDBOX)"; then skip; return 0; fi
  stage "Prerequisites"
  for item in "${ok[@]+"${ok[@]}"}"; do say "${GREEN}✓${RESET} $item"; done
  for item in "${missing[@]+"${missing[@]}"}"; do warn "missing $item"; done
  if ! sandbox_ready "$(current SANDBOX)" || (( ${#missing[@]} > 0 )); then
    printf '\n'; say "Install what is missing, then run setup again."
    exit 1
  fi
  pause
}

sandbox_stage() {
  local now at choice=-1
  now=$(current SANDBOX)
  if (( DONE )) && [[ -n "$now" ]]; then skip; return 0; fi
  stage "Sandbox"
  at=$(index_of "$now" "${SANDBOXES[@]}")
  while (( choice < 0 )); do
    menu choice "$(( at < 0 ? 0 : at ))" "Sandbox" \
      "Where agents run: a podman or docker container, or none: the host, with all your rights." "${SANDBOXES[@]}"
    if (( choice < 0 )) && [[ -n "$now" ]]; then return 0; fi
  done
  printf '\n'
  sandbox_ready "${SANDBOXES[choice]}" || exit 1
  save SANDBOX "${SANDBOXES[choice]}"
}

# ask_token KEY "Prompt" [PREFIX "why"]: hidden input, required, written to
# ENV_FILE; a value starting with PREFIX is asked again.
ask_token() {
  while :; do
    ask_secret "$1" "$2" || exit 1
    if [[ -z "${!1}" ]]; then warn "required"
    elif [[ -n "${3:-}" && "${!1}" == "$3"* ]]; then warn "$4"
    else break; fi
  done
  save "$1" "${!1}"
}

# token_page URL opens URL when KEY has no value yet; otherwise only names it.
token_page() {
  if filled "$1"; then note "for a new one: $2"; else open_url "$2"; fi
}

gh_token_stage() {
  local repos="" key name
  if (( DONE )) && filled GH_TOKEN; then skip; return 0; fi
  while read -r key name; do if [[ -n "$name" ]]; then repos+=" $name"; fi; done <<< "$WIZARD_REPOS"
  stage "GitHub token"
  say "One fine-grained token for every repo of the Workspace."
  token_page GH_TOKEN "https://github.com/settings/personal-access-tokens/new"
  step "Resource owner: the owner of the repos."
  step "Repository access → Only select repositories: $WIZARD_HOME_SLUG${repos:+, and the app repos$repos}."
  step "Repository permissions: Contents, Issues, Pull requests → Read and write; Metadata: Read-only."
  step "Generate token, copy it."
  ask_token GH_TOKEN "Paste the token:"
}

claude_stage() {
  local kind
  if ! uses_provider claudeCode; then skip; return 0; fi
  if (( DONE )) && { filled CLAUDE_CODE_OAUTH_TOKEN || filled ANTHROPIC_API_KEY; }; then skip; return 0; fi
  stage "Claude"
  kind=0
  if filled ANTHROPIC_API_KEY && ! filled CLAUDE_CODE_OAUTH_TOKEN; then kind=1; fi
  menu kind "$kind" "Claude" "How the claudeCode phases log in to Claude." \
    "subscription token (claude setup-token)" "API key"
  printf '\n'
  if (( kind == 0 )); then
    if ! filled CLAUDE_CODE_OAUTH_TOKEN || confirm "Make a new token with claude setup-token?"; then
      say "claude setup-token logs you in in the browser, then prints a token: copy it."
      if command -v claude >/dev/null 2>&1; then claude setup-token || warn "claude setup-token failed"
      else npx -y @anthropic-ai/claude-code setup-token || warn "claude setup-token failed"; fi
    fi
    ask_token CLAUDE_CODE_OAUTH_TOKEN "Paste the token:"
    if filled ANTHROPIC_API_KEY; then write_env ANTHROPIC_API_KEY ""; fi
  elif (( kind == 1 )); then
    token_page ANTHROPIC_API_KEY "https://console.anthropic.com/settings/keys"
    step "Create Key, copy it."
    ask_token ANTHROPIC_API_KEY "Paste the API key:"
    if filled CLAUDE_CODE_OAUTH_TOKEN; then write_env CLAUDE_CODE_OAUTH_TOKEN ""; fi
  elif ! filled CLAUDE_CODE_OAUTH_TOKEN && ! filled ANTHROPIC_API_KEY; then
    warn "A claudeCode phase needs one of them: run setup again."
    exit 1
  fi
}

copilot_stage() {
  if ! uses_provider copilot; then skip; return 0; fi
  if (( DONE )) && filled COPILOT_GITHUB_TOKEN; then skip; return 0; fi
  stage "Copilot token"
  say "copilot phases log in with a fine-grained token; classic tokens (ghp_) do not work."
  token_page COPILOT_GITHUB_TOKEN "https://github.com/settings/personal-access-tokens/new"
  step "Resource owner: your account, the one with Copilot."
  step "Permissions: Copilot Requests."
  step "Generate token, copy it."
  ask_token COPILOT_GITHUB_TOKEN "Paste the token:" ghp_ "a classic token: make a fine-grained one"
}

# is_clone PATH: PATH is a git clone.
is_clone() { [[ -n "$1" ]] && git -C "$1" rev-parse --git-dir >/dev/null 2>&1; }

repos_stage() {
  local keys=() names=() key name i value
  while read -r key name; do if [[ -n "$key" ]]; then keys+=("$key"); names+=("$name"); fi; done <<< "$WIZARD_REPOS"
  if (( ${#keys[@]} == 0 )); then skip; return 0; fi
  if (( DONE )); then
    value=ok
    for key in "${keys[@]}"; do is_clone "$(current "$key")" || value=""; done
    if [[ -n "$value" ]]; then skip; return 0; fi
  fi
  stage "App repos"
  say "Where each app repo is cloned on this machine. Nothing is cloned for you."
  for (( i = 0; i < ${#keys[@]}; i++ )); do
    key=${keys[i]}
    if (( DONE )) && is_clone "$(current "$key")"; then continue; fi
    while :; do
      ask "$key" "Path of ${names[i]}:" || exit 1
      value=${!key}; value=${value//\\//}
      if is_clone "$value"; then save "$key" "$value"; break; fi
      warn "${value:-(empty)} is not a git clone"
    done
  done
}

images_stage() {
  local sandbox image file missing_files=() builds=() i
  sandbox=$(current SANDBOX)
  if [[ "$sandbox" != podman && "$sandbox" != docker ]]; then skip; return 0; fi
  has_image() { "$sandbox" image inspect "$1" >/dev/null 2>&1; }
  if ! has_image "$WIZARD_BASE_IMAGE"; then builds+=("$WIZARD_BASE_IMAGE"); fi
  while read -r image file; do
    if [[ -z "$image" ]] || has_image "$image"; then continue; fi
    if [[ -f "$file" ]]; then builds+=("$image $file"); else missing_files+=("$file"); fi
  done <<< "$WIZARD_IMAGES"
  if (( ${#builds[@]} + ${#missing_files[@]} == 0 )); then skip; return 0; fi
  stage "Repo images"
  if (( ${#missing_files[@]} > 0 )); then
    warn "missing: ${missing_files[*]}: add each, FROM $WIZARD_BASE_IMAGE, then run setup again."
    exit 1
  fi
  say "Missing images. These commands build them, minutes each:"
  printf '\n'
  for i in "${builds[@]}"; do
    read -r image file <<< "$i"
    if [[ -z "$file" ]]; then
      say "$sandbox build -t $image --build-arg AGENT_UID=$(id -u) --build-arg AGENT_GID=$(id -g) $WIZARD_FACTORY_DIR"
    else
      say "npx sandcastle $sandbox build-image --containerfile $file --image-name $image"
    fi
  done
  printf '\n'
  if ! confirm "Build them now?"; then
    warn "A run needs its images: run setup again to build them."
    exit 1
  fi
  for i in "${builds[@]}"; do
    read -r image file <<< "$i"
    if [[ -z "$file" ]]; then
      "$sandbox" build -t "$image" --build-arg "AGENT_UID=$(id -u)" --build-arg "AGENT_GID=$(id -g)" "$WIZARD_FACTORY_DIR"
    else
      npx sandcastle "$sandbox" build-image --containerfile "$file" --image-name "$image"
    fi
  done
}

run_wizard() {

TOTAL_STAGES=8

models_stage
prerequisites_stage
sandbox_stage
gh_token_stage
claude_stage
copilot_stage
repos_stage
images_stage

finish
}

run_wizard "$@"; exit
